CREATE TABLE IF NOT EXISTS settings (id INT PRIMARY KEY, title VARCHAR(120) NOT NULL, points VARCHAR(200) NOT NULL, relay_multiplier INT NOT NULL DEFAULT 2, relay_males INT NOT NULL DEFAULT 4) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS teams (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS athletes (id INT PRIMARY KEY AUTO_INCREMENT, bib VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(80) NOT NULL, gender CHAR(1) NOT NULL, age_group VARCHAR(80) NOT NULL DEFAULT '', team_id INT NOT NULL, FOREIGN KEY(team_id) REFERENCES teams(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS events (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL UNIQUE, kind VARCHAR(20) NOT NULL, gender CHAR(1) NOT NULL DEFAULT 'X', age_group VARCHAR(80) NOT NULL DEFAULT '', direction VARCHAR(4) NOT NULL DEFAULT 'asc', unit VARCHAR(20) NOT NULL DEFAULT '秒') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS results (id INT PRIMARY KEY AUTO_INCREMENT, event_id INT NOT NULL, athlete_id INT NULL, team_id INT NOT NULL, entry_name VARCHAR(80) NOT NULL, performance DECIMAL(12,4) NULL, status VARCHAR(4) NOT NULL DEFAULT 'OK', UNIQUE KEY entry_unique(event_id,team_id,entry_name), UNIQUE KEY athlete_unique(event_id,athlete_id), FOREIGN KEY(event_id) REFERENCES events(id), FOREIGN KEY(athlete_id) REFERENCES athletes(id), FOREIGN KEY(team_id) REFERENCES teams(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS relay_members (result_id INT NOT NULL, athlete_id INT NOT NULL, PRIMARY KEY(result_id,athlete_id), FOREIGN KEY(result_id) REFERENCES results(id) ON DELETE CASCADE, FOREIGN KEY(athlete_id) REFERENCES athletes(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
